WITH with_windows AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, ROW_NUMBER() OVER w_ordered AS seq_no, MAX(humidity) OVER (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS humidity_max_15m, NTILE(5) OVER (PARTITION BY device_code ORDER BY humidity DESC, id) AS humidity_bucket, SUM(pressure) OVER w_hist AS running_pressure, COUNT(temp_c) OVER w_hist_2 AS temp_c_count_1h FROM device_readings WINDOW w_ordered AS (ORDER BY temp_c DESC, id), w_hist AS (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_hist_2 AS (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW)) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, seq_no FROM with_windows ORDER BY device_code DESC
